 72 |     /// @notice Initialize the contract with settings and an admin
 73 |     /// @param admin initial admin user
 74 |     /// @param _settings initial settings for draw
 75 |     function initialize(address admin, Settings memory _settings)
 76 |         public
 77 |         initializer
 78 |     {
 79 |         // Set new settings
 80 |         settings = _settings;
 81 | 
 82 |         // Check values in memory:
 83 |         if (_settings.drawBufferTime < HOUR_IN_SECONDS) {
 84 |             revert REDRAW_TIMELOCK_NEEDS_TO_BE_MORE_THAN_AN_HOUR();
 85 |         }
 86 |         if (_settings.drawBufferTime > MONTH_IN_SECONDS) {
 87 |             revert REDRAW_TIMELOCK_NEEDS_TO_BE_LESS_THAN_A_MONTH();
 88 |         }
 89 | 
 90 |         if (_settings.recoverTimelock < block.timestamp + WEEK_IN_SECONDS) {
 91 |             revert RECOVER_TIMELOCK_NEEDS_TO_BE_AT_LEAST_A_WEEK();
 92 |         }
 93 |         if (
 94 |             _settings.recoverTimelock >
 95 |             block.timestamp + (MONTH_IN_SECONDS * 12)
 96 |         ) {
 97 |             revert RECOVER_TIMELOCK_NEEDS_TO_BE_LESS_THAN_A_YEAR();
 98 |         }
 99 | 
100 |         // If NFT contract address is not a contract
101 |         if (_settings.token.code.length == 0) {
102 |             revert TOKEN_NEEDS_TO_BE_A_CONTRACT(_settings.token);
103 |         }
104 | 
105 |         // If drawing token is not a contract
106 |         if (_settings.drawingToken.code.length == 0) {
107 |             revert TOKEN_NEEDS_TO_BE_A_CONTRACT(_settings.drawingToken);
108 |         }
109 | 
110 |         // Validate token range: end needs to be greater than start
111 |         // and the size of the range needs to be at least 2 (end is exclusive)
112 |         if (
113 |             _settings.drawingTokenEndId < _settings.drawingTokenStartId ||
114 |             _settings.drawingTokenEndId - _settings.drawingTokenStartId < 2
115 |         ) {
116 |             revert DRAWING_TOKEN_RANGE_INVALID();
117 |         }
118 | 
119 |         // Setup owner as admin
120 |         __Ownable_init(admin);
121 | 
122 |         // Emit initialized event for indexing
123 |         emit InitializedDraw(msg.sender, settings);
124 | 
125 |         // Get owner of raffled tokenId and ensure the current owner is the admin
126 |         try
127 |             IERC721EnumerableUpgradeable(_settings.token).ownerOf(
128 |                 _settings.tokenId
129 |             )
